package com.example.starter.exposure.web;

import java.time.Instant;

/**
 * 统一错误响应体。历史字段保持不变，机器可区分的诊断字段追加在末尾，
 * 不适用时为 null。
 *
 * @param status             HTTP 状态码
 * @param error              错误类型
 * @param message            错误信息（不包含堆栈）
 * @param requestId          触发错误的幂等键；无则为 null
 * @param timestamp          错误发生时刻，epoch 毫秒，UTC
 * @param reason             机器可区分原因码（如 ACTIVITY_HOUR_EXHAUSTED）；无则为 null
 * @param actualValue        实际值（如当前已占用名额）；无则为 null
 * @param requiredValue      要求值（如额度上限或本次申请要求数）；无则为 null
 * @param differenceValue    差额（要求值 - 实际值，缺额为负）；无则为 null
 * @param nextAvailableAtUtc 下一可用时刻（下一有剩余名额的自然小时起点），epoch 毫秒 UTC；无则为 null
 */
public record ErrorResponse(
        int status,
        String error,
        String message,
        String requestId,
        long timestamp,
        String reason,
        Long actualValue,
        Long requiredValue,
        Long differenceValue,
        Long nextAvailableAtUtc
) {
    public ErrorResponse(int status, String error, String message, String requestId) {
        this(status, error, message, requestId, Instant.now().toEpochMilli(),
                null, null, null, null, null);
    }

    public ErrorResponse(int status, String error, String message, String requestId,
                         String reason, Long actualValue, Long requiredValue,
                         Long differenceValue, Long nextAvailableAtUtc) {
        this(status, error, message, requestId, Instant.now().toEpochMilli(),
                reason, actualValue, requiredValue, differenceValue, nextAvailableAtUtc);
    }
}

package com.example.starter.exposure.web;

import org.springframework.http.HttpStatus;

/**
 * 额度不足类业务异常（HTTP 429）。携带机器可区分原因码与实际值/要求值/差额/下一可用时刻，
 * 便于调用方区分公告日总额、访客日上限、活动小时耗尽或小时未配置等场景。
 */
public class QuotaExceededException extends ApiException {

    /** 429 的机器可区分原因码。 */
    public enum Reason {
        /** 公告当日总额度已耗尽。 */
        CAMPAIGN_DAILY_TOTAL_EXHAUSTED,
        /** 访客当日上限已耗尽。 */
        VISITOR_DAILY_CAP_EXHAUSTED,
        /** 公告归属活动，但当前 UTC 日未配置 24 小时预算；未配置不得申请。 */
        ACTIVITY_DAY_NOT_CONFIGURED,
        /** 活动当前小时名额已耗尽。 */
        ACTIVITY_HOUR_EXHAUSTED
    }

    private final Reason reason;
    private final Long actualValue;
    private final Long requiredValue;
    private final Long nextAvailableAtUtc;

    public QuotaExceededException(Reason reason, String message,
                                  Long actualValue, Long requiredValue, Long nextAvailableAtUtc) {
        super(HttpStatus.TOO_MANY_REQUESTS, message);
        this.reason = reason;
        this.actualValue = actualValue;
        this.requiredValue = requiredValue;
        this.nextAvailableAtUtc = nextAvailableAtUtc;
    }

    public Reason getReason() {
        return reason;
    }

    public Long getActualValue() {
        return actualValue;
    }

    public Long getRequiredValue() {
        return requiredValue;
    }

    /** 差额：要求值 - 实际值；任一为空返回 null。 */
    public Long getDifferenceValue() {
        if (actualValue == null || requiredValue == null) {
            return null;
        }
        return requiredValue - actualValue;
    }

    public Long getNextAvailableAtUtc() {
        return nextAvailableAtUtc;
    }
}

