                "SELECT COUNT(*) FROM exposure_reservation WHERE activity_id = 'act1' "
                        + "AND utc_hour = 10 AND status = 'RESERVED'", Integer.class);
        assertEquals(hourBudget, reservedCount, "成功预占必须全部落库且归属该活动小时");
    }
}

